namespace sv_c934994be89c4cbbb9d4addafba4153b.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Count; i++)
        {
            var stepIndex = i;
            var stepName = Steps[i];
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="step-item @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                @if (isCompleted)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@stepName</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(isCurrent ? "step" : null)">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@stepName</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> Steps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" value="@FullName" @onchange="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" value="@Email" @onchange="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" value="@Phone" @onchange="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" rows="3" @onchange="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Address</textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-summary">@ValidationMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public string? ValidationMessage { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @onchange="e => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @onchange="e => TitleChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="HandleStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date @(IsCurrent ? "(Current)" : "*")</label>
            <input type="date" value="@EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent" @onchange="HandleEndDateChange" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" @onchange="e => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Description</textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task HandleStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            await StartDateChanged.InvokeAsync(date);
    }

    private async Task HandleEndDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            await EndDateChanged.InvokeAsync(date);
        else
            await EndDateChanged.InvokeAsync(null);
    }

    private async Task HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        await IsCurrentChanged.InvokeAsync(isCurrent);
    }
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];

        <WorkEntryForm
            Index="index"
            Company="@entry.Company"
            Title="@entry.Title"
            StartDate="@entry.StartDate"
            EndDate="@entry.EndDate"
            IsCurrent="@entry.IsCurrent"
            Description="@entry.Description"
            CanRemove="@(Entries.Count > 1)"
            CompanyChanged="@(val => UpdateEntry(index, entry with { Company = val }))"
            TitleChanged="@(val => UpdateEntry(index, entry with { Title = val }))"
            StartDateChanged="@(val => UpdateEntry(index, entry with { StartDate = val }))"
            EndDateChanged="@(val => UpdateEntry(index, entry with { EndDate = val }))"
            IsCurrentChanged="@(val => UpdateEntry(index, entry with { IsCurrent = val, EndDate = val ? null : entry.EndDate }))"
            DescriptionChanged="@(val => UpdateEntry(index, entry with { Description = val }))"
            OnRemove="@(() => RemoveEntry(index))" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-summary">@ValidationMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public string? ValidationMessage { get; set; }
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task UpdateEntry(int index, WorkEntryModel updated)
    {
        var list = new List<WorkEntryModel>(Entries);
        list[index] = updated;
        await EntriesChanged.InvokeAsync(list);
    }

    private async Task AddEntry()
    {
        var list = new List<WorkEntryModel>(Entries) { new() };
        await EntriesChanged.InvokeAsync(list);
    }

    private async Task RemoveEntry(int index)
    {
        var list = new List<WorkEntryModel>(Entries);
        list.RemoveAt(index);
        await EntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext() => await OnNext.InvokeAsync();
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @onchange="e => NameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @onchange="e => RelationshipChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Email" @onchange="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>

        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Phone" @onchange="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> NameChanged { get; set; }
    [Parameter] public EventCallback<string> RelationshipChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];

        <ReferenceForm
            Index="index"
            Name="@reference.Name"
            Relationship="@reference.Relationship"
            Email="@reference.Email"
            Phone="@reference.Phone"
            CanRemove="@(References.Count > 2)"
            NameChanged="@(val => UpdateReference(index, reference with { Name = val }))"
            RelationshipChanged="@(val => UpdateReference(index, reference with { Relationship = val }))"
            EmailChanged="@(val => UpdateReference(index, reference with { Email = val }))"
            PhoneChanged="@(val => UpdateReference(index, reference with { Phone = val }))"
            OnRemove="@(() => RemoveReference(index))" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-summary">@ValidationMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public string? ValidationMessage { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task UpdateReference(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(References);
        list[index] = updated;
        await ReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count < 3)
        {
            var list = new List<ReferenceModel>(References) { new() };
            await ReferencesChanged.InvokeAsync(list);
        }
    }

    private async Task RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            var list = new List<ReferenceModel>(References);
            list.RemoveAt(index);
            await ReferencesChanged.InvokeAsync(list);
        }
    }

    private async Task HandleNext() => await OnNext.InvokeAsync();
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" rows="12" maxlength="@MaxLength"
                  value="@CoverLetter"
                  @oninput="HandleInput">@CoverLetter</textarea>
        <span class="character-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-summary">@ValidationMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public string? ValidationMessage { get; set; }
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        if (value.Length <= MaxLength)
            await CoverLetterChanged.InvokeAsync(value);
        else
            await CoverLetterChanged.InvokeAsync(value[..MaxLength]);
    }

    private async Task HandleNext() => await OnNext.InvokeAsync();
}

@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-data">
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                    @if (!string.IsNullOrEmpty(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    <span>@reference.Email | @reference.Phone</span>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-summary">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="OnSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfoModel Personal { get; set; } = new();
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
