arguments.file_text:
@page "/apply"
@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply
@using sv_c934994be89c4cbbb9d4addafba4153b.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" Steps="stepNames" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalInfo.FullName"
                Email="@personalInfo.Email"
                Phone="@personalInfo.Phone"
                Address="@personalInfo.Address"
                EmailError="@emailError"
                ValidationMessage="@validationMessage"
                IsValidating="@isValidating"
                FullNameChanged="@(val => { personalInfo.FullName = val; ClearValidation(); })"
                EmailChanged="@(val => { personalInfo.Email = val; emailError = null; ClearValidation(); })"
                PhoneChanged="@(val => { personalInfo.Phone = val; ClearValidation(); })"
                AddressChanged="@(val => { personalInfo.Address = val; ClearValidation(); })"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                ValidationMessage="@validationMessage"
                EntriesChanged="@(entries => { workEntries = entries; ClearValidation(); })"
                OnNext="HandleWorkHistoryNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="references"
                ValidationMessage="@validationMessage"
                ReferencesChanged="@(refs => { references = refs; ClearValidation(); })"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                ValidationMessage="@validationMessage"
                CoverLetterChanged="@(val => { coverLetter = val; ClearValidation(); })"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                Personal="personalInfo"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                IsSubmitting="@isSubmitting"
                IsSubmitted="@isSubmitted"
                ApplicationId="@applicationId"
                ErrorMessage="@validationMessage"
                OnEditStep="GoToStep"
                OnSubmit="HandleSubmit"
                OnBack="GoBack" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private static readonly IReadOnlyList<string> stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int currentStep;
    private string? validationMessage;
    private string? emailError;
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void ClearValidation()
    {
        validationMessage = null;
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
            ClearValidation();
        }
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
            ClearValidation();
        }
    }

    private async Task HandlePersonalInfoNext()
    {
        if (string.IsNullOrWhiteSpace(personalInfo.FullName) ||
            string.IsNullOrWhiteSpace(personalInfo.Email) ||
            string.IsNullOrWhiteSpace(personalInfo.Phone) ||
            string.IsNullOrWhiteSpace(personalInfo.Address))
        {
            validationMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        emailError = null;
        StateHasChanged();

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
            if (!isValid)
            {
                emailError = "Please enter a valid email address.";
                isValidating = false;
                return;
            }
        }
        catch
        {
            emailError = "Unable to validate email. Please try again.";
            isValidating = false;
            return;
        }

        isValidating = false;
        currentStep = 1;
        ClearValidation();
    }

    private void HandleWorkHistoryNext()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationMessage = "Please fill in the company name and job title for all positions.";
                return;
            }
        }

        currentStep = 2;
        ClearValidation();
    }

    private void HandleReferencesNext()
    {
        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) ||
                string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) ||
                string.IsNullOrWhiteSpace(reference.Phone))
            {
                validationMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        currentStep = 3;
        ClearValidation();
    }

    private void HandleCoverLetterNext()
    {
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationMessage = "Please write a cover letter before proceeding.";
            return;
        }

        currentStep = 4;
        ClearValidation();
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        validationMessage = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            applicationId = id;
            isSubmitted = true;
        }
        catch
        {
            validationMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: '';
    position: absolute;
    top: 1.25rem;
    left: 2rem;
    right: 2rem;
    height: 2px;
    background: #e0e0e0;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0;
    gap: 0.5rem;
}

.completed .step-button {
    cursor: pointer;
}

.step-icon {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    background: #e0e0e0;
    color: #999;
}

.step-item.current .step-icon {
    background: #2563eb;
    color: white;
}

.step-item.completed .step-icon {
    background: #16a34a;
    color: white;
}

.step-item.future .step-icon {
    background: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    max-width: 80px;
}

.step-item.current .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #16a34a;
}

.step-item.future .step-label {
    color: #999;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    font-size: 0.875rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.field-error {
    color: #dc2626;
    font-size: 0.75rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-summary {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.75rem;
    color: #666;
    margin-top: 0.25rem;
}

.character-count.over-limit {
    color: #dc2626;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f9fafb;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #374151;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e5e7eb;
}

.btn {
    padding: 0.625rem 1.5rem;
    border-radius: 4px;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: background 0.2s;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-primary {
    background: #2563eb;
    color: white;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-outline {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-outline:hover {
    background: #f3f4f6;
}

.btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-secondary:hover {
    background: #e5e7eb;
}

.btn-danger {
    background: #dc2626;
    color: white;
}

.btn-danger:hover {
    background: #b91c1c;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Review Step */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #374151;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
}

.review-data dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
    font-size: 0.875rem;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #374151;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h3 {
    color: #16a34a;
    font-size: 1.5rem;
}

