{"file_text": "@page "/apply"
@namespace sv_c934994be89c4cbbb9d4addafba4153b.Components.Pages.Apply
@using sv_c934994be89c4cbbb9d4addafba4153b.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" Steps="stepNames" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalInfo.FullName"
                Email="@personalInfo.Email"
                Phone="@personalInfo.Phone"
                Address="@personalInfo.Address"
                EmailError="@emailError"
                ValidationMessage="@validationMessage"
                IsValidating="@isValidating"
                FullNameChanged="@(val => { personalInfo.FullName = val; ClearValidation(); })"
                EmailChanged="@(val => { personalInfo.Email = val; emailError = null; ClearValidation(); })"
                PhoneChanged="@(val => { personalInfo.Phone = val; ClearValidation(); })"
                AddressChanged="@(val => { personalInfo.Address = val; ClearValidation(); })"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                ValidationMessage="@validationMessage"
                EntriesChanged="@(entries => { workEntries = entries; ClearValidation(); })"
                OnNext="HandleWorkHistoryNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="references"
                ValidationMessage="@validationMessage"
                ReferencesChanged="@(refs => { references = refs; ClearValidation(); })"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                ValidationMessage="@validationMessage"
                CoverLetterChanged="@(val => { coverLetter = val; ClearValidation(); })"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                Personal="personalInfo"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                IsSubmitting="@isSubmitting"
                IsSubmitted="@isSubmitted"
                ApplicationId="@applicationId"
                ErrorMessage="@validationMessage"
                OnEditStep="GoToStep"
                OnSubmit="HandleSubmit"
                OnBack="GoBack" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private static readonly IReadOnlyList<string> stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int currentStep;
    private string? validationMessage;
    private string? emailError;
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void ClearValidation()
    {
        validationMessage = null;
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
            ClearValidation();
        }
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
            ClearValidation();
        }
    }

    private async Task HandlePersonalInfoNext()
    {
        if (string.IsNullOrWhiteSpace(personalInfo.FullName) ||
            string.IsNullOrWhiteSpace(personalInfo.Email) ||
            string.IsNullOrWhiteSpace(personalInfo.Phone) ||
            string.IsNullOrWhiteSpace(personalInfo.Address))
        {
            validationMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        emailError = null;
        StateHasChanged();

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
            if (!isValid)
            {
                emailError = "Please enter a valid email address.";
                isValidating = false;
                return;
            }
        }
        catch
        {
            emailError = "Unable to validate email. Please try again.";
            isValidating = false;
            return;
        }

        isValidating = false;
        currentStep = 1;
        ClearValidation();
    }

    private void HandleWorkHistoryNext()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationMessage = "Please fill in the company name and job title for all positions.";
                return;
            }
        }

        currentStep = 2;
        ClearValidation();
    }

    private void HandleReferencesNext()
    {
        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) ||
                string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) ||
                string.IsNullOrWhiteSpace(reference.Phone))
            {
                validationMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        currentStep = 3;
        ClearValidation();
    }

    private void HandleCoverLetterNext()
    {
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationMessage = "Please write a cover letter before proceeding.";
            return;
        }

        currentStep = 4;
        ClearValidation();
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        validationMessage = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            applicationId = id;
            isSubmitted = true;
        }
        catch
        {
            validationMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
