    private Task OnEmailChange(ChangeEventArgs e) => EmailChanged.InvokeAsync(GetString(e));
    private Task OnPhoneChange(ChangeEventArgs e) => PhoneChanged.InvokeAsync(GetString(e));
    private Task HandleRemove() => OnRemove.InvokeAsync();
}
